const today = new Date();
const twoDaysAgo = new Date(today.getTime() - 2 * 24 * 60 * 60 * 1000);

const fromDate = twoDaysAgo.toISOString().split('T')[0];
const toDate = today.toISOString().split('T')[0];

const searchQueries = [
  {
    query: 'Web3 OR tokenization OR blockchain',
    category: 'technology',
    priority: 1,
    region: 'global'
  },
  {
    query: 'AI education OR "AI for social good"',
    category: 'technology',
    priority: 1,
    region: 'global'
  },
  {
    query: 'DeFi OR "decentralized finance"',
    category: 'technology',
    priority: 1,
    region: 'global'
  },
  {
    query: 'fintech innovation OR digital banking',
    category: 'technology',
    priority: 2,
    region: 'global'
  },
  {
    query: 'social entrepreneurship OR impact investing',
    category: 'business',
    priority: 2,
    region: 'global'
  },
  {
    query: 'UAE technology OR Dubai fintech',
    category: 'technology',
    priority: 2,
    region: 'middle_east'
  },
  {
    query: 'Saudi Arabia AI OR NEOM',
    category: 'technology',
    priority: 2,
    region: 'middle_east'
  },
  {
    query: 'sustainable retail OR retail tech',
    category: 'technology',
    priority: 3,
    region: 'global'
  }
];

return searchQueries.map(q => ({
  json: {
    searchQuery: q.query,
    category: q.category,
    priority: q.priority,
    region: q.region,
    fromDate: fromDate,
    toDate: toDate,
    pageSize: 20
  }
}));

const items = $input.all();
const normalizedArticles = [];

for (const item of items) {
  const json = item.json;
  let articles = [];

  // NewsAPI.org format
  if (json.articles && Array.isArray(json.articles)) {
    articles = json.articles.map(article => ({
      title: article.title,
      description: article.description,
      url: article.url,
      image: article.urlToImage,
      source: article.source?.name || 'Unknown',
      author: article.author,
      publishedAt: article.publishedAt,
      content: article.content,
      apiSource: 'newsapi.org'
    }));
  }

  // NewsAPI.ai format
  else if (json.articles?.results) {
    articles = json.articles.results.map(article => ({
      title: article.title,
      description: article.body?.substring(0, 300) || '',
      url: article.url,
      image: article.image,
      source: article.source?.title || 'Unknown',
      author: article.authors?.[0]?.name || null,
      publishedAt: `${article.date}T${article.time}Z`,
      content: article.body,
      socialShares: (article.shares?.facebook || 0) + (article.shares?.twitter || 0),
      apiSource: 'newsapi.ai'
    }));
  }

  // MediaStack format
  else if (json.data && Array.isArray(json.data)) {
    articles = json.data.map(article => ({
      title: article.title,
      description: article.description,
      url: article.url,
      image: article.image,
      source: article.source || 'Unknown',
      author: article.author,
      publishedAt: article.published_at,
      content: article.description,
      country: article.country,
      apiSource: 'mediastack'
    }));
  }

  const validArticles = articles.filter(a => a.title && a.url);
  normalizedArticles.push(...validArticles);
}

// Remove duplicates
const uniqueArticles = [];
const seenUrls = new Set();

for (const article of normalizedArticles) {
  if (!seenUrls.has(article.url)) {
    seenUrls.add(article.url);
    uniqueArticles.push(article);
  }
}

console.log(`Normalized ${uniqueArticles.length} unique articles from News APIs`);

return uniqueArticles.map(a => ({ json: a }));

const items = $input.all();
const scoredArticles = [];

for (const item of items) {
  const article = item.json;
  let score = 0;

  if (!article.title || !article.url) continue;

  const title = (article.title || '').toLowerCase();
  const description = (article.description || '').toLowerCase();
  const content = (article.content || '').toLowerCase();
  const fullText = `${title} ${description} ${content}`;

  // RECENCY
  const pubDate = new Date(article.publishedAt || article.pubDate || article.date);
  const now = new Date();
  const hoursOld = (now - pubDate) / (1000 * 60 * 60);

  if (hoursOld <= 6) score += 20;
  else if (hoursOld <= 12) score += 15;
  else if (hoursOld <= 24) score += 10;
  else if (hoursOld <= 48) score += 5;
  else score += 2;

  // TIER 1: Core Topics
  const tier1 = [
    { keyword: 'web3', points: 40 },
    { keyword: 'tokenization', points: 40 },
    { keyword: 'blockchain', points: 35 },
    { keyword: 'defi', points: 38 },
    { keyword: 'ai social impact', points: 45 },
    { keyword: 'ai education', points: 42 }
  ];

  tier1.forEach(k => {
    if (fullText.includes(k.keyword)) {
      score += k.points;
      if (title.includes(k.keyword)) score += 10;
    }
  });

  // TIER 2: High Relevance
  const tier2 = [
    { keyword: 'fintech', points: 30 },
    { keyword: 'social entrepreneurship', points: 32 },
    { keyword: 'edtech', points: 28 },
    { keyword: 'sustainable retail', points: 28 }
  ];

  tier2.forEach(k => {
    if (fullText.includes(k.keyword)) {
      score += k.points;
      if (title.includes(k.keyword)) score += 6;
    }
  });

  // MIDDLE EAST BONUS
  const middleEast = ['uae', 'dubai', 'saudi', 'neom', 'qatar'];
  middleEast.forEach(me => {
    if (fullText.includes(me)) score += 20;
  });

  // COMBOS
  const hasWeb3 = fullText.includes('web3') || fullText.includes('blockchain');
  const hasAI = fullText.includes('ai') || fullText.includes('artificial intelligence');
  const hasSocial = fullText.includes('social impact') || fullText.includes('social entrepreneur');

  if (hasWeb3 && hasSocial) score += 25;
  if (hasAI && hasSocial) score += 25;

  // NEWS API BONUSES
  if (article.apiSource === 'newsapi.ai' && article.socialShares > 1000) score += 15;
  if (article.apiSource === 'mediastack' && article.country === 'ae') score += 12;

  // IMAGE BONUS
  if (article.image || article.urlToImage) score += 8;

  scoredArticles.push({
    ...article,
    relevanceScore: score
  });
}

const topArticles = scoredArticles
  .sort((a, b) => b.relevanceScore - a.relevanceScore)
  .slice(0, 20);

console.log(`Top 5 Articles:`);
topArticles.slice(0, 5).forEach((a, i) => {
  console.log(`${i+1}. [${a.relevanceScore}pts] ${a.title.substring(0, 60)}...`);
});

return topArticles.map(a => ({ json: a }));

const items = $input.all();

for (const item of items) {
  const html = item.json.html || item.json.data;
  let imageUrl = '';

  if (html) {
    // Try multiple methods to find the best image

    // Method 1: Open Graph image (most reliable for articles)
    let match = html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["'][^>]*>/i);
    if (match) {
      imageUrl = match[1];
    }

    // Method 2: Twitter card image
    if (!imageUrl) {
      match = html.match(/<meta[^>]*name=["']twitter:image["'][^>]*content=["']([^"']+)["'][^>]*>/i);
      if (match) {
        imageUrl = match[1];
      }
    }

    // Method 3: Featured/hero images (common in blog posts)
    if (!imageUrl) {
      const featuredSelectors = [
        /<img[^>]*class=["'][^"']*featured[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*hero[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*post-image[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*wp-post-image[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i
      ];

      for (const regex of featuredSelectors) {
        match = html.match(regex);
        if (match) {
          imageUrl = match[1];
          break;
        }
      }
    }

    // Method 4: First image in article content
    if (!imageUrl) {
      match = html.match(/<(?:article|div[^>]*class=["'][^"']*(?:content|post|article)[^"']*["'])[^>]*>.*?<img[^>]*src=["']([^"']+)["'][^>]*>/is);
      if (match) {
        imageUrl = match[1];
      }
    }

    // Method 5: Any reasonably sized image (width > 300px)
    if (!imageUrl) {
      const imgMatches = html.match(/<img[^>]*src=["']([^"']+)["'][^>]*>/gi);
      if (imgMatches) {
        for (const imgTag of imgMatches) {
          const srcMatch = imgTag.match(/src=["']([^"']+)["']/);
          const widthMatch = imgTag.match(/width=["']?(\d+)/);

          if (srcMatch && (!widthMatch || parseInt(widthMatch[1]) > 300)) {
            imageUrl = srcMatch[1];
            break;
          }
        }
      }
    }

    // Clean up relative URLs
    if (imageUrl && imageUrl.startsWith('//')) {
      imageUrl = 'https:' + imageUrl;
    } else if (imageUrl && imageUrl.startsWith('/')) {
      const linkUrl = item.json.link || '';
      const baseUrl = linkUrl.match(/^https?:\/\/[^\/]+/);
      if (baseUrl) {
        imageUrl = baseUrl[0] + imageUrl;
      }
    }

    // Validate it's actually an image
    if (imageUrl && !imageUrl.match(/\.(jpg|jpeg|png|gif|webp|svg)(\?.*)?$/i)) {
      // Check if it might be a valid image URL without extension
      if (!imageUrl.includes('image') && !imageUrl.includes('photo') && !imageUrl.includes('pic')) {
        imageUrl = '';
      }
    }
  }

  // Add image data to your item
  item.json.imageUrl = imageUrl;
  item.json.hasImage = !!imageUrl;

  // Log for debugging
  if (imageUrl) {
    console.log(`Found image: ${imageUrl}`);
  } else {
    console.log('No image found for article');
  }
}

return items;

// Enhanced random with timestamp seed
const seed = Date.now() + Math.random() * 1000;
const randomIndex = Math.floor(seed % items.length);
const selectedItem = items[randomIndex];

return [{ json: selectedItem.json }];

const items = $input.all();
const scoredItems = [];

for (const item of items) {
  const feedItem = item.json;
  let score = 0;

  // Skip if no title or link
  if (!feedItem.title || !feedItem.link) continue;

  // Score based on how recent (simple version)
  const pubDate = new Date(feedItem.pubDate || feedItem.date);
  const now = new Date();
  const hoursOld = (now - pubDate) / (1000 * 60 * 60);

  if (hoursOld <= 24) score += 5;
  else if (hoursOld <= 48) score += 3;
  else score += 1;

  // Score based on title keywords (customize these)
  const title = (feedItem.title || '').toLowerCase();
  const keywords = ['ai', 'tech', 'innovation', 'startup', 'emerging tech', 'jobs of the future'];

  keywords.forEach(keyword => {
    if (title.includes(keyword)) score += 2;
  });

  scoredItems.push({
    title: feedItem.title,
    link: feedItem.link,
    description: feedItem.description,
    pubDate: feedItem.pubDate,
    score: score
  });
}

// Get top 3
const topItems = scoredItems
  .sort((a, b) => b.score - a.score)
  .slice(0, 15)
  .map(item => ({ json: item }));

return topItems;
